// JS half of the click-sound drift gate (#805).
//
// The live click is synthesised here from static/js/clickSounds.js; exports
// are rendered in Python from the same table (app/pipeline/click_sounds.py).
// tests/fixtures/click_sounds.json holds Python's measurements of every
// preset voice (generated by tests/_click_sounds_fixture.py and asserted by
// tests/test_click_sounds.py). This file measures the browser synthesis the
// same way and fails if any preset drifts: a different length, an attack in
// another place, another envelope or another brightness.
//
// Tolerances: the two sides run the same formulas in float64, so the only
// expected difference is the last bit of sin/pow/exp between V8 and numpy.
// Anything past these bounds is a real change in the sound.
//
// Run:  node tests/js/click-sounds.test.mjs

import { readFileSync } from "node:fs";
import {
  CLICK_SOUNDS,
  CLICK_SOUND_IDS,
  DEFAULT_CLICK_SOUND,
  normaliseClickSound,
  renderVoice,
} from "../../static/js/clickSounds.js";

const fixture = JSON.parse(
  readFileSync(new URL("../fixtures/click_sounds.json", import.meta.url), "utf8"),
);

let pass = 0,
  fail = 0;
const check = (name, cond, detail = "") => {
  if (cond) pass++;
  else {
    fail++;
    console.log(`FAIL  ${name}${detail ? "  -- " + detail : ""}`);
  }
};

// Iterative radix-2 FFT, power spectrum of the real input zero-padded to `size`.
function rfftPower(x, size) {
  const re = new Float64Array(size);
  const im = new Float64Array(size);
  re.set(x);
  for (let i = 1, j = 0; i < size; i++) {
    let bit = size >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
    }
  }
  for (let len = 2; len <= size; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < size; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * wr - im[b] * wi;
        const ti = re[b] * wi + im[b] * wr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
      }
    }
  }
  const power = new Float64Array(size / 2 + 1);
  for (let k = 0; k <= size / 2; k++) power[k] = re[k] * re[k] + im[k] * im[k];
  return power;
}

function measure(x, sampleRate, frameSec) {
  const hop = Math.max(1, Math.round(frameSec * sampleRate));
  const envelope = [];
  for (let i = 0; i < x.length; i += hop) {
    const end = Math.min(x.length, i + hop);
    let s = 0;
    for (let k = i; k < end; k++) s += x[k] * x[k];
    envelope.push(Math.sqrt(s / (end - i)));
  }
  let size = 1;
  while (size < x.length) size *= 2;
  const power = rfftPower(x, size);
  let num = 0,
    den = 0;
  for (let k = 0; k < power.length; k++) {
    num += ((k * sampleRate) / size) * power[k];
    den += power[k];
  }
  let peakIndex = 0,
    absSum = 0;
  for (let i = 0; i < x.length; i++) {
    absSum += Math.abs(x[i]);
    if (Math.abs(x[i]) > Math.abs(x[peakIndex])) peakIndex = i;
  }
  return {
    length: x.length,
    peakIndex,
    peak: Math.abs(x[peakIndex]),
    envelope,
    centroid: den > 0 ? num / den : 0,
    absSum,
  };
}

// The fixture covers every preset, so a preset added to the table without
// regenerating it fails here rather than shipping unpinned.
const pinned = new Set(fixture.voices.map((v) => v.sound));
check("every preset is in the fixture", CLICK_SOUND_IDS.every((id) => pinned.has(id)),
  CLICK_SOUND_IDS.filter((id) => !pinned.has(id)).join(","));
check("the fixture has no preset the table lost", [...pinned].every((id) => CLICK_SOUND_IDS.includes(id)));

for (const want of fixture.voices) {
  const tag = `${want.sound} level ${want.level} @ ${want.sampleRate}`;
  const got = measure(renderVoice(want.sound, want.level, want.sampleRate), want.sampleRate, fixture.frameSec);
  check(`${tag}: length`, got.length === want.length, `${got.length} vs ${want.length}`);
  check(`${tag}: peak position`, Math.abs(got.peakIndex - want.peakIndex) <= 1, `${got.peakIndex} vs ${want.peakIndex}`);
  check(`${tag}: peak level`, Math.abs(got.peak - want.peak) <= 1e-4, `${got.peak} vs ${want.peak}`);
  const envDiff = Math.max(...got.envelope.map((e, i) => Math.abs(e - (want.envelope[i] ?? Infinity))));
  check(`${tag}: envelope`, got.envelope.length === want.envelope.length && envDiff <= 1e-4, `max diff ${envDiff}`);
  check(`${tag}: spectral centroid`, Math.abs(got.centroid - want.centroid) <= 1, `${got.centroid} vs ${want.centroid}`);
  check(`${tag}: sample sum`, Math.abs(got.absSum - want.absSum) <= 1e-3 * Math.max(1, want.absSum), `${got.absSum} vs ${want.absSum}`);
}

// The default is Classic, and anything unknown falls back to it.
check("default is classic", DEFAULT_CLICK_SOUND === "classic" && CLICK_SOUNDS.default === "classic");
check("unknown id falls back", normaliseClickSound("nope") === "classic" && normaliseClickSound(null) === "classic");
check("known id is kept", normaliseClickSound("cowbell") === "cowbell");

// Level matching: no voice at full click volume reaches full scale.
for (const id of CLICK_SOUND_IDS) {
  for (const level of [0, 1, 2]) {
    const v = renderVoice(id, level, 48000);
    const peak = v.reduce((m, s) => Math.max(m, Math.abs(s)), 0);
    check(`${id} level ${level}: peak below full scale`, peak < 0.99, String(peak));
  }
}

console.log(`click-sounds: ${pass} passed, ${fail} failed`);
if (fail) process.exit(1);
